module ForestBuilder #(\n    parameter MAX_V = 8,\n    parameter DATA_WIDTH = 8,\n    parameter EDGE_WIDTH = 4\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] V,\n    input wire [DATA_WIDTH-1:0] degrees [0:MAX_V-1],\n    output reg possible,\n    output reg done,\n    output reg edge_valid,\n    output reg [EDGE_WIDTH-1:0] edge_a,\n    output reg [EDGE_WIDTH-1:0] edge_b\n);\n\n    reg [DATA_WIDTH-1:0] deg [0:MAX_V-1];\n    reg [3:0] comp_id [0:MAX_V-1];\n    reg [3:0] V_reg;\n    reg [DATA_WIDTH-1:0] sum_deg, max_deg, m;\n    reg [3:0] u, v;\n    reg [3:0] idx;\n    reg [3:0] best_deg, best_u;\n    reg found_v;\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] FIND_U = 3'd2;\n    localparam [2:0] FIND_V = 3'd3;\n    localparam [2:0] ADD_EDGE = 3'd4;\n    localparam [2:0] CHECK_DONE = 3'd5;\n    localparam [2:0] FINISHED = 3'd6;\n\n    reg [2:0] state, next_state;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            possible <= 1'b0;\n            done <= 1'b0;\n            edge_valid <= 1'b0;\n            edge_a <= {EDGE_WIDTH{1'b0}};\n            edge_b <= {EDGE_WIDTH{1'b0}};\n            state <= IDLE;\n            V_reg <= 4'd0;\n            sum_deg <= {DATA_WIDTH{1'b0}};\n            max_deg <= {DATA_WIDTH{1'b0}};\n            m <= {DATA_WIDTH{1'b0}};\n            u <= 4'd0;\n            v <= 4'd0;\n            idx <= 4'd0;\n            best_deg <= 4'd0;\n            best_u <= 4'd0;\n            found_v <= 1'b0;\n            for (integer i = 0; i < MAX_V; i = i + 1) begin\n                deg[i] <= {DATA_WIDTH{1'b0}};\n                comp_id[i] <= 4'd0;\n            end\n        end else begin\n            state <= next_state;\n            edge_valid <= 1'b0;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        V_reg <= V;\n                        for (integer i = 0; i < MAX_V; i = i + 1) begin\n                            if (i < V) deg[i] <= degrees[i]; else deg[i] <= {DATA_WIDTH{1'b0}};\n                            comp_id[i] <= i;\n                        end\n                        sum_deg <= {DATA_WIDTH{1'b0}};\n                        max_deg <= {DATA_WIDTH{1'b0}};\n                        m <= {DATA_WIDTH{1'b0}};\n                        idx <= 4'd0;\n                        next_state <= INIT;\n                    end else next_state <= IDLE;\n                end\n                INIT: begin\n                    if (idx < V_reg) begin\n                        if (deg[idx] > 0) begin\n                            sum_deg <= sum_deg + deg[idx];\n                            m <= m + 1;\n                            if (deg[idx] > max_deg) max_deg <= deg[idx];\n                        end\n                        idx <= idx + 1;\n                        next_state <= INIT;\n                    end else begin\n                        if (sum_deg == 0) begin\n                            possible <= 1'b1; done <= 1'b1; next_state <= IDLE;\n                        end else if (sum_deg[0] == 1 || (m > 0 && (max_deg > (m-1) || sum_deg > 2*(m-1)))) begin\n                            possible <= 1'b0; done <= 1'b1; next_state <= IDLE;\n                        end else begin\n                            possible <= 1'b1;\n                            best_deg <= 4'd0;\n                            best_u <= 4'd0;\n                            idx <= 4'd0;\n                            next_state <= FIND_U;\n                        end\n                    end\n                end\n                FIND_U: begin\n                    if (idx < V_reg) begin\n                        if (deg[idx] > best_deg) begin\n                            best_deg <= deg[idx];\n                            best_u <= idx;\n                        end\n                        idx <= idx + 1;\n                        next_state <= FIND_U;\n                    end else begin\n                        if (best_deg == 0) begin\n                            done <= 1'b1; next_state <= IDLE;\n                        end else begin\n                            u <= best_u;\n                            best_deg <= 4'd0;\n                            idx <= 4'd0;\n                            found_v <= 1'b0;\n                            next_state <= FIND_V;\n                        end\n                    end\n                end\n                FIND_V: begin\n                    if (idx < V_reg) begin\n                        if (idx != u && deg[idx] > 0 && comp_id[idx] != comp_id[u]) begin\n                            v <= idx;\n                            found_v <= 1'b1;\n                        end\n                        idx <= idx + 1;\n                        next_state <= FIND_V;\n                    end else begin\n                        if (found_v) next_state <= ADD_EDGE;\n                        else begin\n                            possible <= 1'b0; done <= 1'b1; next_state <= IDLE;\n                        end\n                        idx <= 4'd0;\n                    end\n                end\n                ADD_EDGE: begin\n                    edge_a <= u + 1;\n                    edge_b <= v + 1;\n                    edge_valid <= 1'b1;\n                    deg[u] <= deg[u] - 1;\n                    deg[v] <= deg[v] - 1;\n                    for (integer i = 0; i < MAX_V; i = i + 1) begin\n                        if (i < V_reg && comp_id[i] == comp_id[v]) comp_id[i] <= comp_id[u];\n                    end\n                    next_state <= CHECK_DONE;\n                end\n                CHECK_DONE: begin\n                    if (idx < V_reg) begin\n                        if (deg[idx] > 0) begin\n                            idx <= 4'd0;\n                            best_deg <= 4'd0;\n                            next_state <= FIND_U;\n                        end else begin\n                            idx <= idx + 1;\n                            next_state <= CHECK_DONE;\n                        end\n                    end else begin\n                        done <= 1'b1;\n                        next_state <= IDLE;\n                    end\n                end\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule